import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './Crud.css';

function Crud() {
    const [tablaSeleccionada, setTablaSeleccionada] = useState('');
    const [catequizandos, setCatequizandos] = useState([]);
    const [form, setForm] = useState({
        nombres: '',
        apellidos: '',
        contacto: '',
        fechaNacimiento: '',
        feBautismo: false,
        inscripciones: [],
        sacramentos: [],
    });
    const [editId, setEditId] = useState(null);
    const [nuevoContacto, setNuevoContacto] = useState('');

    // Listar catequizandos
    const fetchCatequizandos = async () => {
        try {
            const res = await axios.get('http://127.0.0.1:5000/api/catequizando');
            setCatequizandos(res.data);
        } catch (error) {
            console.error('Error fetching catequizandos:', error);
        }
    };

    useEffect(() => {
        if (tablaSeleccionada === 'Catequizandos') {
            fetchCatequizandos();
        }
    }, [tablaSeleccionada]);

    // Crear catequizando
    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await axios.post('http://127.0.0.1:5000/api/catequizando', form);
            setForm({
                nombres: '',
                apellidos: '',
                contacto: '',
                fechaNacimiento: '',
                feBautismo: false,
                inscripciones: [],
                sacramentos: [],
            });
            fetchCatequizandos();
        } catch (error) {
            console.error('Error creating catequizando:', error);
        }
    };

    // Actualizar catequizando
    const handleUpdate = async (id) => {
        try {
            await axios.put(`http://127.0.0.1:5000/api/catequizando/${id}`, { contacto: nuevoContacto });
            setEditId(null);
            setNuevoContacto('');
            fetchCatequizandos();
        } catch (error) {
            console.error('Error updating catequizando:', error);
        }
    };

    // Eliminar catequizando
    const handleDelete = async (id) => {
        try {
            await axios.delete(`http://127.0.0.1:5000/api/catequizando/${id}`);
            fetchCatequizandos();
        } catch (error) {
            console.error('Error deleting catequizando:', error);
        }
    };

    return (
        <div className="crud-container">
            <h2 className="crud-title">CRUD</h2>
            {/* Selector de tabla */}
            <form>
                <label className="form-label" htmlFor="tabla">Selecciona la tabla:</label>
                <select
                    id="tabla"
                    value={tablaSeleccionada}
                    onChange={(e) => setTablaSeleccionada(e.target.value)}
                    required
                >
                    <option value="">-- Selecciona una tabla --</option>
                    <option value="Catequizandos">Catequizandos</option>
                </select>
            </form>

            {/* CRUD para Catequizandos */}
            {tablaSeleccionada === 'Catequizandos' && (
                <>
                    <form onSubmit={handleSubmit}>
                        <label className="form-label">Nombres</label>
                        <input
                            placeholder="Nombres"
                            value={form.nombres}
                            onChange={(e) => setForm({ ...form, nombres: e.target.value })}
                            required
                        />
                        <label className="form-label">Apellidos</label>
                        <input
                            placeholder="Apellidos"
                            value={form.apellidos}
                            onChange={(e) => setForm({ ...form, apellidos: e.target.value })}
                            required
                        />
                        <label className="form-label">Contacto</label>
                        <input
                            placeholder="Contacto"
                            value={form.contacto}
                            onChange={(e) => setForm({ ...form, contacto: e.target.value })}
                            required
                        />
                        <label className="form-label">Fecha de Nacimiento</label>
                        <input
                            type="date"
                            value={form.fechaNacimiento}
                            onChange={(e) => setForm({ ...form, fechaNacimiento: e.target.value })}
                            required
                        />
                        <label className="form-label">Fe Bautismo</label>
                        <input
                            type="checkbox"
                            checked={form.feBautismo}
                            onChange={(e) => setForm({ ...form, feBautismo: e.target.checked })}
                        />
                        <button type="submit">Crear</button>
                    </form>
                    <table className="crud-table">
                        <thead>
                            <tr>
                                <th>ID</th>
                                <th>Nombres</th>
                                <th>Apellidos</th>
                                <th>Contacto</th>
                                <th>Fecha Nacimiento</th>
                                <th>Fe Bautismo</th>
                                <th>Acciones</th>
                            </tr>
                        </thead>
                        <tbody>
                            {catequizandos.map((c) => (
                                <tr key={c._id}>
                                    <td>{c._id}</td>
                                    <td>{c.nombres}</td>
                                    <td>{c.apellidos}</td>
                                    <td>
                                        {editId === c._id ? (
                                            <input
                                                value={nuevoContacto}
                                                onChange={(e) => setNuevoContacto(e.target.value)}
                                            />
                                        ) : (
                                            c.contacto
                                        )}
                                    </td>
                                    <td>{new Date(c.fecha_nacimiento).toLocaleDateString()}</td>
                                    <td>{c.fe_bautismo ? 'Sí' : 'No'}</td>
                                    <td>
                                        {editId === c._id ? (
                                            <button type="button" onClick={() => handleUpdate(c._id)}>Guardar</button>
                                        ) : (
                                            <button
                                                type="button"
                                                onClick={() => {
                                                    setEditId(c._id);
                                                    setNuevoContacto(c.contacto);
                                                }}
                                            >
                                                Editar
                                            </button>
                                        )}
                                        <button type="button" onClick={() => handleDelete(c._id)}>Eliminar</button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </>
            )}
        </div>
    );
}

export default Crud;
